export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  maxNights: number;
  minStay?: number;
  maxGuests: number;
  baseRate: number;
  peakSurcharge: number;
  guestSurcharge?: number;
  serviceFee: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    maxNights: 14,
    maxGuests: 2,
    baseRate: 80,
    peakSurcharge: 30,
    serviceFee: 0,
  },
  suite: {
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    peakSurcharge: 60,
    guestSurcharge: 25,
    serviceFee: 0,
  },
  villa: {
    maxNights: 28,
    minStay: 3,
    maxGuests: 8,
    baseRate: 300,
    peakSurcharge: 120,
    serviceFee: 500,
  },
};

interface BookingRequest {
  category: string;
  nights: number;
  guests: number;
  season: string;
  loyaltyYears: number;
  coupon: unknown;
}

function isLoyal(req: BookingRequest): boolean {
  return req.loyaltyYears >= 3 || req.coupon === "VIP";
}

const MIN_GUESTS = 1;

function parseRequest(raw: unknown): { ok: true; req: BookingRequest } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const r = raw as Record<string, unknown>;
  if (!Number.isInteger(r.loyaltyYears) || (r.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = r.category as string;
  const cfg = CATEGORIES[category];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const nights = r.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (cfg.minStay !== undefined && nights < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = r.guests as number;
  if (!Number.isInteger(guests) || guests < MIN_GUESTS || guests > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (r.season !== "low" && r.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return {
    ok: true,
    req: {
      category,
      nights,
      guests,
      season: r.season as string,
      loyaltyYears: r.loyaltyYears as number,
      coupon: r.coupon,
    },
  };
}

function price(req: BookingRequest, cfg: CategoryConfig): number {
  let total = cfg.baseRate * req.nights;
  if (req.season === "high") {
    total += cfg.peakSurcharge * req.nights;
  }
  if (isLoyal(req)) {
    total -= Math.floor(total / 10);
  }
  if (cfg.guestSurcharge !== undefined && req.guests > 2) {
    total += cfg.guestSurcharge;
  }
  return total + cfg.serviceFee;
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!parsed.ok) {
    return parsed;
  }

  const cfg = CATEGORIES[parsed.req.category];
  const total = price(parsed.req, cfg);
  const policy = parsed.req.coupon === "VIP" || parsed.req.loyaltyYears > 2 ? "flex" : "strict";
  const line = parsed.req.category + ":" + String(parsed.req.nights) + "n:" + String(total) + ":" + policy;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  maxNights: number;
  maxGuests: number;
  base: number;
  highSurcharge: number;
  minStay?: number;
  extraGuestOver?: number;
  extraGuestCharge?: number;
  flatFee?: number;
}

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: { name: "standard", maxNights: 14, maxGuests: 2, base: 80, highSurcharge: 30 },
  suite: {
    name: "suite",
    maxNights: 21,
    maxGuests: 4,
    base: 150,
    highSurcharge: 60,
    extraGuestOver: 2,
    extraGuestCharge: 25,
  },
  villa: {
    name: "villa",
    maxNights: 28,
    maxGuests: 8,
    base: 300,
    highSurcharge: 120,
    minStay: 3,
    flatFee: 500,
  },
};

interface ParsedBooking {
  ok: boolean;
  error?: string;
  nights?: number;
  guests?: number;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyalty = req.loyaltyYears;
  if (!Number.isInteger(loyalty) || (loyalty as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[req.category as string];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const parsed = validate(req, cfg);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }

  const eligible = (loyalty as number) >= 3 || req.coupon === "VIP";
  const total = price(cfg, parsed.nights as number, parsed.guests as number, req.season as string, eligible);
  const policy = eligible ? "flex" : "strict";
  const line = `${cfg.name}:${parsed.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

function validate(req: Record<string, unknown>, cfg: CategoryConfig): ParsedBooking {
  const nights = req.nights;
  if (!Number.isInteger(nights) || (nights as number) < 1 || (nights as number) > cfg.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (cfg.minStay !== undefined && (nights as number) < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  const guests = req.guests;
  if (!Number.isInteger(guests) || (guests as number) < 1 || (guests as number) > cfg.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  return { ok: true, nights: nights as number, guests: guests as number };
}

function baseRate(cfg: CategoryConfig, season: string): number {
  return season === "high" ? cfg.base + cfg.highSurcharge : cfg.base;
}

function price(cfg: CategoryConfig, nights: number, guests: number, season: string, eligible: boolean): number {
  let total = baseRate(cfg, season) * nights;
  if (eligible) {
    total -= Math.floor(total / 10);
  }
  if (cfg.extraGuestOver !== undefined && guests > cfg.extraGuestOver) {
    total += cfg.extraGuestCharge as number;
  }
  if (cfg.flatFee !== undefined) {
    total += cfg.flatFee;
  }
  return total;
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Category = "standard" | "suite" | "villa";

interface CategoryConfig {
  perNight: number;
  highSurchargePerNight: number;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  loyaltyThreshold: number;
  guestSurcharge: (guests: number) => number;
  flatFee: number;
}

const CATEGORIES: Record<Category, CategoryConfig> = {
  standard: {
    perNight: 80,
    highSurchargePerNight: 30,
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    loyaltyThreshold: 3,
    guestSurcharge: () => 0,
    flatFee: 0,
  },
  suite: {
    perNight: 150,
    highSurchargePerNight: 60,
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    loyaltyThreshold: 3,
    guestSurcharge: (guests) => (guests > 2 ? 25 : 0),
    flatFee: 0,
  },
  villa: {
    perNight: 300,
    highSurchargePerNight: 120,
    minNights: 3,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    loyaltyThreshold: 3,
    guestSurcharge: () => 0,
    flatFee: 500,
  },
};

interface BookingParams {
  nights: number;
  season: "low" | "high";
  guests: number;
  vip: boolean;
  perks: boolean;
}

function isNonNegativeInt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function inRange(value: unknown, min: number, max: number): value is number {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function hasLoyaltyPerks(loyaltyYears: number, threshold: number): boolean {
  return loyaltyYears >= threshold;
}

type FieldRule = (
  req: Record<string, unknown>,
  config: CategoryConfig,
  category: Category,
) => string | null;

const RULES: FieldRule[] = [
  (req) => (isNonNegativeInt(req.loyaltyYears) ? null : "bad loyalty"),
  (req, config) => (inRange(req.nights, 1, config.maxNights) ? null : "bad nights"),
  (req, config, category) =>
    !(category === "villa" && (req.nights as number) < config.minNights)
      ? null
      : "villa minimum stay",
  (req, config) =>
    inRange(req.guests, config.minGuests, config.maxGuests) ? null : "bad guests",
  (req) => (req.season === "low" || req.season === "high" ? null : "bad season"),
];

function quote(
  req: Record<string, unknown>,
  category: Category,
  config: CategoryConfig,
): QuoteResult {
  for (const rule of RULES) {
    const error = rule(req, config, category);
    if (error !== null) {
      return { ok: false, error };
    }
  }

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as "low" | "high";
  const vip = req.coupon === "VIP";
  const perks = vip || hasLoyaltyPerks(req.loyaltyYears as number, config.loyaltyThreshold);

  const total = price(config, nights, season, guests, perks);
  const policy = perks ? "flex" : "strict";
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

function price(
  config: CategoryConfig,
  nights: number,
  season: "low" | "high",
  guests: number,
  perks: boolean,
): number {
  let total = config.perNight * nights;
  if (season === "high") {
    total += config.highSurchargePerNight * nights;
  }
  if (perks) {
    total -= Math.floor(total / 10);
  }
  total += config.guestSurcharge(guests);
  total += config.flatFee;
  return total;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isNonNegativeInt(req.loyaltyYears)) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category;
  if (category !== "standard" && category !== "suite" && category !== "villa") {
    return { ok: false, error: "unknown category" };
  }
  return quote(req, category, CATEGORIES[category]);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryRules {
  name: string;
  minNights: number;
  maxNights: number;
  minNightsStrict?: number;
  minGuests: number;
  maxGuests: number;
  basePerNight: number;
  highPerNight: number;
  extraGuestsFee?: number;
  flatFee?: number;
}

const CATEGORY_RULES: Record<string, CategoryRules> = {
  standard: { name: "standard", minNights: 1, maxNights: 14, minGuests: 1, maxGuests: 2, basePerNight: 80, highPerNight: 30 },
  suite:    { name: "suite",    minNights: 1, maxNights: 21, minGuests: 1, maxGuests: 4, basePerNight: 150, highPerNight: 60, extraGuestsFee: 25 },
  villa:    { name: "villa",    minNights: 1, maxNights: 28, minNightsStrict: 3, minGuests: 1, maxGuests: 8, basePerNight: 300, highPerNight: 120, flatFee: 500 },
};

const LOW_SEASONS = new Set(["low", "high"]);
const LOYALTY_DISCOUNT_THRESHOLD = 3;
const FLEX_POLICY_LOYALTY = 3;

interface ValidatedQuote {
  rules: CategoryRules;
  nights: number;
  guests: number;
  season: string;
  loyaltyYears: number;
  isVip: boolean;
}

function isInt(value: unknown): value is number {
  return Number.isInteger(value);
}

function validateLoyalty(req: Record<string, unknown>): number | QuoteResult {
  const loyaltyYears = req.loyaltyYears;
  if (!isInt(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return loyaltyYears;
}

function resolveCategory(req: Record<string, unknown>): CategoryRules | QuoteResult {
  const category = req.category;
  if (typeof category !== "string" || !(category in CATEGORY_RULES)) {
    return { ok: false, error: "unknown category" };
  }
  return CATEGORY_RULES[category];
}

function validateNights(req: Record<string, unknown>, rules: CategoryRules): number | QuoteResult {
  const nights = req.nights;
  if (!isInt(nights) || nights < rules.minNights || nights > rules.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (rules.minNightsStrict !== undefined && nights < rules.minNightsStrict) {
    return { ok: false, error: "villa minimum stay" };
  }
  return nights;
}

function validateGuests(req: Record<string, unknown>, rules: CategoryRules): number | QuoteResult {
  const guests = req.guests;
  if (!isInt(guests) || guests < rules.minGuests || guests > rules.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  return guests;
}

function validateSeason(req: Record<string, unknown>): string | QuoteResult {
  const season = req.season;
  if (typeof season !== "string" || !LOW_SEASONS.has(season)) {
    return { ok: false, error: "bad season" };
  }
  return season;
}

function parseRequest(raw: unknown): ValidatedQuote | QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = validateLoyalty(req);
  if (typeof loyaltyYears !== "number") {
    return loyaltyYears;
  }

  const rules = resolveCategory(req);
  if ("error" in rules) {
    return rules;
  }

  const nights = validateNights(req, rules);
  if (typeof nights !== "number") {
    return nights;
  }

  const guests = validateGuests(req, rules);
  if (typeof guests !== "number") {
    return guests;
  }

  const season = validateSeason(req);
  if (typeof season !== "string") {
    return season;
  }

  return { rules, nights, guests, season, loyaltyYears, isVip: req.coupon === "VIP" };
}

function roomCharge(rules: CategoryRules, nights: number, highSeason: boolean): number {
  let total = rules.basePerNight * nights;
  if (highSeason) {
    total += rules.highPerNight * nights;
  }
  return total;
}

function applyDiscount(total: number, discounted: boolean): number {
  return discounted ? total - Math.floor(total / 10) : total;
}

function applySurcharges(total: number, rules: CategoryRules, guests: number): number {
  if (rules.extraGuestsFee !== undefined && guests > 2) {
    total += rules.extraGuestsFee;
  }
  if (rules.flatFee !== undefined) {
    total += rules.flatFee;
  }
  return total;
}

function pickPolicy(isVip: boolean, loyaltyYears: number): string {
  return isVip || loyaltyYears >= FLEX_POLICY_LOYALTY ? "flex" : "strict";
}

function computeQuote(v: ValidatedQuote): QuoteResult {
  const { rules, nights, guests, season, loyaltyYears, isVip } = v;
  const highSeason = season === "high";

  let total = roomCharge(rules, nights, highSeason);
  total = applyDiscount(total, isVip || loyaltyYears >= LOYALTY_DISCOUNT_THRESHOLD);
  total = applySurcharges(total, rules, guests);

  const policy = pickPolicy(isVip, loyaltyYears);
  const line = `${rules.name}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!parsed.ok) {
    return parsed;
  }
  return computeQuote(parsed);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface QuoteRequest {
  category: string;
  nights: number;
  guests: number;
  season: string;
  loyaltyYears: number;
  coupon: string | undefined;
}

interface CategorySpec {
  label: string;
  maxNights: number;
  maxGuests: number;
  baseRate: number;
  highBonus: number;
  minStay?: number;
  flatSurcharge?: number;
  guestSurcharge?: number;
}

const SPECS: Record<string, CategorySpec> = {
  standard: { label: "standard", maxNights: 14, maxGuests: 2, baseRate: 80, highBonus: 30 },
  suite: {
    label: "suite",
    maxNights: 21,
    maxGuests: 4,
    baseRate: 150,
    highBonus: 60,
    guestSurcharge: 25,
  },
  villa: {
    label: "villa",
    maxNights: 28,
    maxGuests: 8,
    baseRate: 300,
    highBonus: 120,
    flatSurcharge: 500,
    minStay: 3,
  },
};

function parseRequest(raw: unknown): QuoteResult | QuoteRequest {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const r = raw as Record<string, unknown>;
  if (!Number.isInteger(r.loyaltyYears) || (r.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return {
    category: r.category as string,
    nights: r.nights as number,
    guests: r.guests as number,
    season: r.season as string,
    loyaltyYears: r.loyaltyYears as number,
    coupon: typeof r.coupon === "string" ? (r.coupon as string) : undefined,
  };
}

function validateNights(req: QuoteRequest, spec: CategorySpec): string | undefined {
  if (!Number.isInteger(req.nights) || req.nights < 1 || req.nights > spec.maxNights) {
    return "bad nights";
  }
  if (spec.minStay !== undefined && req.nights < spec.minStay) {
    return "villa minimum stay";
  }
  return undefined;
}

function validateGuests(req: QuoteRequest, spec: CategorySpec): string | undefined {
  if (!Number.isInteger(req.guests) || req.guests < 1 || req.guests > spec.maxGuests) {
    return "bad guests";
  }
  return undefined;
}

function validateSeason(req: QuoteRequest): string | undefined {
  if (req.season !== "low" && req.season !== "high") {
    return "bad season";
  }
  return undefined;
}

function computeTotal(req: QuoteRequest, spec: CategorySpec, preferred: boolean): number {
  let total = spec.baseRate * req.nights;
  if (req.season === "high") {
    total += spec.highBonus * req.nights;
  }
  const guestFee = spec.guestSurcharge ?? 0;
  const flatFee = spec.flatSurcharge ?? 0;
  if (preferred) {
    total -= Math.floor(total / 10);
  }
  if (guestFee > 0 && req.guests > 2) {
    total += guestFee;
  }
  if (flatFee > 0) {
    total += flatFee;
  }
  return total;
}

function quoteCategory(req: QuoteRequest, spec: CategorySpec): QuoteResult {
  const error =
    validateNights(req, spec) ?? validateGuests(req, spec) ?? validateSeason(req);
  if (error !== undefined) {
    return { ok: false, error };
  }
  const preferred = req.loyaltyYears >= 3 || req.coupon === "VIP";
  const total = computeTotal(req, spec, preferred);
  const policy = preferred ? "flex" : "strict";
  const line =
    spec.label + ":" + String(req.nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!("category" in parsed)) {
    return parsed;
  }
  const spec = SPECS[parsed.category];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }
  return quoteCategory(parsed, spec);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  readonly line: string;
  readonly nightsMin: number;
  readonly nightsMax: number;
  readonly minStay: number;
  readonly guestsMax: number;
  readonly baseRate: number;
  readonly highBonus: number;
  readonly guestSurcharge: number;
  readonly surchargeOver: number;
  readonly extraCharge: number;
}

const CATEGORIES: Readonly<Record<string, CategoryConfig>> = {
  standard: {
    line: "standard",
    nightsMin: 1,
    nightsMax: 14,
    minStay: 1,
    guestsMax: 2,
    baseRate: 80,
    highBonus: 30,
    guestSurcharge: 0,
    surchargeOver: Number.MAX_SAFE_INTEGER,
    extraCharge: 0,
  },
  suite: {
    line: "suite",
    nightsMin: 1,
    nightsMax: 21,
    minStay: 1,
    guestsMax: 4,
    baseRate: 150,
    highBonus: 60,
    guestSurcharge: 25,
    surchargeOver: 2,
    extraCharge: 0,
  },
  villa: {
    line: "villa",
    nightsMin: 1,
    nightsMax: 28,
    minStay: 3,
    guestsMax: 8,
    baseRate: 300,
    highBonus: 120,
    guestSurcharge: 0,
    surchargeOver: Number.MAX_SAFE_INTEGER,
    extraCharge: 500,
  },
};

interface ValidQuote {
  readonly ok: true;
  readonly nights: number;
  readonly guests: number;
  readonly season: "low" | "high";
  readonly premium: boolean;
}

type CategoryCheck = { readonly ok: false; readonly error: string } | ValidQuote;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function isIntegerInRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
}

function checkCategory(req: Record<string, unknown>, cfg: CategoryConfig): CategoryCheck {
  const { nights, guests } = req;
  if (!isIntegerInRange(nights, cfg.nightsMin, cfg.nightsMax)) {
    return { ok: false, error: "bad nights" };
  }
  if ((nights as number) < cfg.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!isIntegerInRange(guests, 1, cfg.guestsMax)) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }
  return {
    ok: true,
    nights: nights as number,
    guests: guests as number,
    season: req.season as "low" | "high",
    premium: (req.loyaltyYears as number) >= 3 || req.coupon === "VIP",
  };
}

function computeTotal(q: ValidQuote, cfg: CategoryConfig): number {
  let total = cfg.baseRate * q.nights;
  if (q.season === "high") {
    total += cfg.highBonus * q.nights;
  }
  if (q.premium) {
    total -= Math.floor(total / 10);
  }
  if (q.guests > cfg.surchargeOver) {
    total += cfg.guestSurcharge;
  }
  return total + cfg.extraCharge;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (!isRecord(raw)) {
    return { ok: false, error: "malformed request" };
  }
  if (!Number.isInteger(raw.loyaltyYears) || (raw.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const cfg = CATEGORIES[String(raw.category)];
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }

  const checked = checkCategory(raw, cfg);
  if (!checked.ok) {
    return checked;
  }

  const total = computeTotal(checked, cfg);
  const policy = checked.premium ? "flex" : "strict";
  const line = `${cfg.line}:${checked.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
