}

interface CategoryRules {
  label: string;
  maxNights: number;
  maxGuests: number;
  ratePerNight: number;
  peakSurchargePerNight: number;
  minNights: number;
  guestSurcharge?: number;
  fixedFee: number;
  discountFromLoyalty: number;
  discountLoyaltyExclusive: boolean;
  flexFromLoyalty: number;
  flexLoyaltyExclusive: boolean;
}

const RULES: Record<string, CategoryRules> = {
  standard: {
    label: "standard",
    maxNights: 14,
    maxGuests: 2,
    ratePerNight: 80,
    peakSurchargePerNight: 30,
    minNights: 1,
    fixedFee: 0,
    discountFromLoyalty: 3,
    discountLoyaltyExclusive: false,
    flexFromLoyalty: 2,
    flexLoyaltyExclusive: true,
  },
  suite: {
    label: "suite",
    maxNights: 21,
    maxGuests: 4,
    ratePerNight: 150,
    peakSurchargePerNight: 60,
    minNights: 1,
    guestSurcharge: 25,
    fixedFee: 0,
    discountFromLoyalty: 3,
    discountLoyaltyExclusive: false,
    flexFromLoyalty: 3,
