    discountFromLoyalty: 2,
    discountLoyaltyExclusive: true,
    flexFromLoyalty: 3,
    flexLoyaltyExclusive: false,
  },
};

function meetsThreshold(value: number, from: number, exclusive: boolean): boolean {
  return exclusive ? value > from : value >= from;
}

function hasDiscount(req: Record<string, unknown>, rules: CategoryRules): boolean {
  return (
    req.coupon === "VIP" ||
    meetsThreshold(req.loyaltyYears as number, rules.discountFromLoyalty, rules.discountLoyaltyExclusive)
  );
}

function hasFlexibleCancellation(req: Record<string, unknown>, rules: CategoryRules): boolean {
  return (
    req.coupon === "VIP" ||
    meetsThreshold(req.loyaltyYears as number, rules.flexFromLoyalty, rules.flexLoyaltyExclusive)
  );
}

function price(rules: CategoryRules, req: Record<string, unknown>): QuoteResult {
  const nights = req.nights as number;

  let total = rules.ratePerNight * nights;
  if (req.season === "high") {
    total += rules.peakSurchargePerNight * nights;
  }
  if (hasDiscount(req, rules)) {
    total -= Math.floor(total / 10);
  }
  if (rules.guestSurcharge !== undefined && (req.guests as number) > 2) {
    total += rules.guestSurcharge;
  }
  total += rules.fixedFee;

  const policy = hasFlexibleCancellation(req, rules) ? "flex" : "strict";
  const line = `${rules.label}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

function validateBooking(req: Record<string, unknown>, rules: CategoryRules): QuoteResult | null {
  const nights = req.nights as number;
  const guests = req.guests as number;

  if (!Number.isInteger(nights) || nights < 1 || nights > rules.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < rules.minNights) {
    return { ok: false, error: `${rules.label} minimum stay` };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > rules.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return null;
}

export function quoteBooking(raw: unknown): QuoteResult {
