    return { ok: false, error: "bad loyalty" };
  }

  const rules = RULES[req.category as string];
  if (!rules) {
    return { ok: false, error: "unknown category" };
  }

  const invalid = validateBooking(req, rules);
  if (invalid) {
    return invalid;
  }

  return price(rules, req);
}

export interface QuoteResult {
