  canDiscount: (loyaltyYears: number, coupon: unknown) => boolean;
  canFlex: (loyaltyYears: number, coupon: unknown) => boolean;
}

const CONFIGS: Record<Category, CategoryConfig> = {
  standard: {
    maxNights: 14,
    minStay: 1,
    maxGuests: 2,
    base: 80,
    highPerNight: 30,
    extra: 0,
    extraFor: () => false,
    canDiscount: (loyaltyYears, coupon) => loyaltyYears >= 3 || coupon === "VIP",
