  },
};

const CATEGORY_NAMES = Object.keys(CONFIGS) as Category[];

function validate(raw: unknown): { ok: false; error: string } | { ok: true; req: Validated } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  if (typeof req.category !== "string" || !(CATEGORY_NAMES as string[]).includes(req.category)) {
    return { ok: false, error: "unknown category" };
  }
  const category = req.category as Category;
  const config = CONFIGS[category];

  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < 1 || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < config.minStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < 1 || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  return {
    ok: true,
    req: {
      category,
      nights,
      guests,
      season: req.season,
      loyaltyYears: req.loyaltyYears as number,
      coupon: req.coupon,
    },
  };
}

function price(req: Validated): { total: number; policy: "strict" | "flex"; line: string } {
  const config = CONFIGS[req.category];

  let total = config.base * req.nights;
  if (req.season === "high") {
    total += config.highPerNight * req.nights;
  }
  if (config.canDiscount(req.loyaltyYears, req.coupon)) {
    total -= Math.floor(total / 10);
  }
  if (config.extraFor(req.guests)) {
    total += config.extra;
  }

  const policy = config.canFlex(req.loyaltyYears, req.coupon) ? "flex" : "strict";
  const line = `${req.category}:${req.nights}n:${total}:${policy}`;
  return { total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const result = validate(raw);
  if (!result.ok) {
    return { ok: false, error: result.error };
  }
  return { ok: true, ...price(result.req) };
}

export interface QuoteResult {
