type RawRequest = Record<string, unknown>;

function asInteger(v: unknown): number | null {
  return Number.isInteger(v) ? (v as number) : null;
}

function inRange(v: unknown, min: number, max: number): boolean {
  const n = asInteger(v);
  return n !== null && n >= min && n <= max;
}

function isLowOrHighSeason(v: unknown): boolean {
  return v === "low" || v === "high";
}

function hasDiscount(loyaltyYears: number, coupon: unknown): boolean {
  return coupon === "VIP" || loyaltyYears > 2;
}

function isFlexiblePolicy(loyaltyYears: number, coupon: unknown): boolean {
  return coupon === "VIP" || loyaltyYears > 2;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as RawRequest;

  const loyalty = asInteger(req.loyaltyYears);
  if (loyalty === null || loyalty < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const config = CATEGORIES[req.category as string];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const nights = asInteger(req.nights);
  if (nights === null) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minimumStay !== undefined && nights < config.minimumStay) {
    return { ok: false, error: "villa minimum stay" };
  }

  const guests = asInteger(req.guests);
  if (guests === null || guests < config.minGuests || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (!isLowOrHighSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }

  const season = req.season as "low" | "high";
  const coupon = req.coupon;

  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highSeasonPremium * nights;
  }

  if (hasDiscount(loyalty, coupon)) {
    total -= Math.floor(total / 10);
  }

  if (config.extraGuestFee !== undefined && guests > (config.extraGuestThreshold ?? 0)) {
    total += config.extraGuestFee;
  }
  total += config.flatFee;

  const policy = isFlexiblePolicy(loyalty, coupon) ? "flex" : "strict";

  const line = `${req.category}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
