  forcedFee: number;
  discounts: (loyaltyYears: number, coupon: unknown) => boolean;
  flexes: (loyaltyYears: number, coupon: unknown) => boolean;
}

interface Booking {
  category: string;
  nights: number;
  guests: number;
  season: string;
  loyaltyYears: number;
  coupon: unknown;
}

const CATEGORIES: Record<string, CategorySpec> = {
  standard: {
    maxNights: 14,
    minStay: 1,
    maxGuests: 2,
    baseRate: 80,
    highSurcharge: 30,
    extraGuestCharge: 0,
    forcedFee: 0,
    discounts: (y, c) => y >= 3 || c === "VIP",
    flexes: (y, c) => c === "VIP" || y > 2,
  },
  suite: {
    maxNights: 21,
    minStay: 1,
    maxGuests: 4,
    baseRate: 150,
    highSurcharge: 60,
    extraGuestCharge: 25,
    forcedFee: 0,
    discounts: (y, c) => c === "VIP" || y >= 3,
    flexes: (y, c) => c === "VIP" || y >= 3,
  },
  villa: {
    maxNights: 28,
    minStay: 3,
    maxGuests: 8,
    baseRate: 300,
    highSurcharge: 120,
    extraGuestCharge: 0,
    forcedFee: 500,
    discounts: (y, c) => y > 2 || c === "VIP",
    flexes: (y, c) => c === "VIP" || y >= 3,
  },
};

function isRecord(raw: unknown): raw is Record<string, unknown> {
  return typeof raw === "object" && raw !== null;
}

function validateLoyalty(req: Record<string, unknown>) {
  if (!Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return "bad loyalty";
  }
  return null;
}

function resolveCategory(req: Record<string, unknown>) {
  const category = req.category as string;
  if (!(category in CATEGORIES)) {
    return { error: "unknown category" as const };
  }
  return { spec: CATEGORIES[category], name: category };
}

function validateNights(req: Record<string, unknown>, spec: CategorySpec) {
  const nights = req.nights as number;
  if (!Number.isInteger(req.nights) || nights < 1 || nights > spec.maxNights) {
    return "bad nights";
  }
  if (nights < spec.minStay) {
    return "villa minimum stay";
  }
  return null;
}

function validateGuests(req: Record<string, unknown>, spec: CategorySpec) {
  const guests = req.guests as number;
  if (!Number.isInteger(req.guests) || guests < 1 || guests > spec.maxGuests) {
    return "bad guests";
  }
  return null;
}

function validateSeason(req: Record<string, unknown>) {
  const season = req.season as string;
  if (season !== "low" && season !== "high") {
    return "bad season";
  }
  return null;
}

function parseBooking(raw: unknown): { ok: false; error: string } | { ok: true; booking: Booking } {
  if (!isRecord(raw)) {
    return { ok: false, error: "malformed request" };
  }
  const loyaltyError = validateLoyalty(raw);
  if (loyaltyError) {
    return { ok: false, error: loyaltyError };
  }
  const resolved = resolveCategory(raw);
  if (!("spec" in resolved)) {
    return { ok: false, error: resolved.error };
  }
  const nightsError = validateNights(raw, resolved.spec);
  if (nightsError) {
    return { ok: false, error: nightsError };
  }
  const guestsError = validateGuests(raw, resolved.spec);
  if (guestsError) {
    return { ok: false, error: guestsError };
  }
  const seasonError = validateSeason(raw);
  if (seasonError) {
    return { ok: false, error: seasonError };
  }

  return {
    ok: true,
    booking: {
      category: resolved.name,
      nights: raw.nights as number,
      guests: raw.guests as number,
      season: raw.season as string,
      loyaltyYears: raw.loyaltyYears as number,
      coupon: raw.coupon,
    },
  };
}

function priceBooking(b: Booking): QuoteResult {
  const spec = CATEGORIES[b.category];

  let total = spec.baseRate * b.nights;
  if (b.season === "high") {
    total += spec.highSurcharge * b.nights;
  }
  if (spec.discounts(b.loyaltyYears, b.coupon)) {
    total -= Math.floor(total / 10);
  }
  if (b.guests > 2) {
    total += spec.extraGuestCharge;
  }
  total += spec.forcedFee;

  const policy = spec.flexes(b.loyaltyYears, b.coupon) ? "flex" : "strict";
  const line = `${b.category}:${String(b.nights)}n:${String(total)}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseBooking(raw);
  return parsed.ok ? priceBooking(parsed.booking) : parsed;
}

