interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = stock[event.item] ?? 0;
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] ?? 0;
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        tryFulfillQueue(stock, queue, pendingWants, reserved, orders);
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const held = stock[event.item] ?? 0;
      stock[event.item] = held + (event.qty as number);
      tryFulfillQueue(stock, queue, pendingWants, reserved, orders);
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] ?? 0;
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        tryFulfillQueue(stock, queue, pendingWants, reserved, orders);
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

function tryFulfillQueue(
  stock: Record<string, number>,
  queue: string[],
  pendingWants: Record<string, Want>,
  reserved: Record<string, Want>,
  orders: Record<string, string>
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position = position - 1;
    }
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface WorkState {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  orders: Record<string, string>;
  rejected: number;
}

type EventError = { error: string };

function drained(state: WorkState): void {
  const queue = state.queue;
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = state.pendingWants[pendingId];
    if (want === undefined) {
      queue.splice(position, 1);
      position = position - 1;
      continue;
    }
    const onHand = state.stock[want.item] === undefined ? 0 : state.stock[want.item];
    if (onHand < want.qty) {
      continue;
    }
    state.stock[want.item] = onHand - want.qty;
    state.reserved[pendingId] = { item: want.item, qty: want.qty };
    state.orders[pendingId] = "reserved";
    delete state.pendingWants[pendingId];
    queue.splice(position, 1);
    position = position - 1;
  }
}

function released(state: WorkState, id: string, finalStatus: string): void {
  const holding = state.reserved[id];
  if (holding !== undefined) {
    const back = state.stock[holding.item] === undefined ? 0 : state.stock[holding.item];
    state.stock[holding.item] = back + holding.qty;
  }
  delete state.reserved[id];
  state.orders[id] = finalStatus;
}

function requireString(event: Record<string, unknown>, index: number, field: string): string | EventError {
  const value = event[field];
  if (typeof value !== "string" || value.length === 0) {
    return { error: "event " + index + ": bad " + field };
  }
  return value;
}

function requireQty(event: Record<string, unknown>, index: number, field: string): number | EventError {
  const value = event[field];
  if (!Number.isInteger(value) || (value as number) < 1) {
    return { error: "event " + index + ": bad " + field };
  }
  return value as number;
}

function handleOrder(state: WorkState, event: Record<string, unknown>, index: number): EventError | null {
  const id = requireString(event, index, "id");
  if (typeof id !== "string") return id;
  if (state.orders[id] !== undefined) {
    return { error: "event " + index + ": duplicate order" };
  }
  const item = requireString(event, index, "item");
  if (typeof item !== "string") return item;
  const qty = requireQty(event, index, "qty");
  if (typeof qty !== "number") return qty;
  const available = state.stock[item] === undefined ? 0 : state.stock[item];
  if (available >= qty) {
    state.stock[item] = available - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function handleCancel(state: WorkState, event: Record<string, unknown>, index: number): EventError | null {
  const id = requireString(event, index, "id");
  if (typeof id !== "string") return id;
  if (state.reserved[id] !== undefined) {
    released(state, id, "cancelled");
    drained(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(state: WorkState, event: Record<string, unknown>, index: number): EventError | null {
  const id = requireString(event, index, "id");
  if (typeof id !== "string") return id;
  if (event.qty !== undefined) {
    const qty = requireQty(event, index, "qty");
    if (typeof qty !== "number") return qty;
  }
  const held = state.reserved[id];
  if (held === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === held.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < held.qty) {
    state.reserved[id].qty = held.qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleRestock(state: WorkState, event: Record<string, unknown>, index: number): EventError | null {
  const item = requireString(event, index, "item");
  if (typeof item !== "string") return item;
  const qty = requireQty(event, index, "qty");
  if (typeof qty !== "number") return qty;
  const held = state.stock[item] === undefined ? 0 : state.stock[item];
  state.stock[item] = held + qty;
  drained(state);
  return null;
}

function handleExpire(state: WorkState, event: Record<string, unknown>, index: number): EventError | null {
  const id = requireString(event, index, "id");
  if (typeof id !== "string") return id;
  if (state.reserved[id] !== undefined) {
    released(state, id, "expired");
    drained(state);
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

type Handler = (state: WorkState, event: Record<string, unknown>, index: number) => EventError | null;

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function loadStock(raw: unknown): Record<string, number> | EventError {
  if (typeof raw !== "object" || raw === null) {
    return { error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = raw as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return stock;
}

function applyEvents(state: WorkState, events: unknown[]): EventError | null {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return { error: "event " + index + ": malformed" };
    }
    const record = event as Record<string, unknown>;
    const handler = typeof record.type === "string" ? HANDLERS[record.type] : undefined;
    if (handler === undefined) {
      return { error: "event " + index + ": bad type" };
    }
    const result = handler(state, record, index);
    if (result !== null) {
      return result;
    }
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stock = loadStock(input.stock);
  if ("error" in stock) {
    return { ok: false, error: stock.error };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: WorkState = {
    stock,
    reserved: {},
    pendingWants: {},
    queue: [],
    orders: {},
    rejected: 0,
  };

  const eventError = applyEvents(state, input.events);
  if (eventError !== null) {
    return { ok: false, error: eventError.error };
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface FulfillmentState {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (
  state: FulfillmentState,
  event: Record<string, unknown>,
  index: number
) => FulfillmentResult | undefined;

function badEvent(index: number, reason: string): FulfillmentResult {
  return { ok: false, error: "event " + index + ": " + reason };
}

function needId(event: Record<string, unknown>, index: number): FulfillmentResult | undefined {
  if (typeof event.id === "string" && event.id.length > 0) {
    return undefined;
  }
  return badEvent(index, "bad id");
}

function needItem(event: Record<string, unknown>, index: number): FulfillmentResult | undefined {
  if (typeof event.item === "string" && event.item.length > 0) {
    return undefined;
  }
  return badEvent(index, "bad item");
}

function needQty(qty: unknown, index: number, required: boolean): FulfillmentResult | undefined {
  if (qty === undefined && !required) {
    return undefined;
  }
  if (Number.isInteger(qty) && (qty as number) >= 1) {
    return undefined;
  }
  return badEvent(index, "bad qty");
}

function fetchStock(stock: Record<string, number>, item: string): number {
  return stock[item] ?? 0;
}

function fulfillFromQueue(state: FulfillmentState): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = fetchStock(state.stock, want.item);
    if (onHand >= want.qty) {
      state.stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(state: FulfillmentState, id: string, status: string): void {
  const holding = state.reserved[id];
  state.stock[holding.item] = fetchStock(state.stock, holding.item) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  fulfillFromQueue(state);
}

function addStock(state: FulfillmentState, item: string, qty: number): void {
  state.stock[item] = fetchStock(state.stock, item) + qty;
  fulfillFromQueue(state);
}

const handleOrder: Handler = (state, event, index) => {
  const idErr = needId(event, index);
  if (idErr) return idErr;
  if (state.orders[event.id as string] !== undefined) {
    return badEvent(index, "duplicate order");
  }
  const itemErr = needItem(event, index);
  if (itemErr) return itemErr;
  const qtyErr = needQty(event.qty, index, true);
  if (qtyErr) return qtyErr;
  const qty = event.qty as number;
  const available = fetchStock(state.stock, event.item as string);
  if (available >= qty) {
    state.stock[event.item as string] = available - qty;
    state.reserved[event.id as string] = { item: event.item as string, qty };
    state.orders[event.id as string] = "reserved";
  } else {
    state.queue.push(event.id as string);
    state.pendingWants[event.id as string] = { item: event.item as string, qty };
    state.orders[event.id as string] = "backordered";
  }
  return undefined;
};

function handleRelease(status: string, allowBackorder: boolean): Handler {
  return (state, event, index) => {
    const idErr = needId(event, index);
    if (idErr) return idErr;
    const id = event.id as string;
    if (state.reserved[id] !== undefined) {
      releaseReservation(state, id, status);
    } else if (allowBackorder && state.orders[id] === "backordered") {
      state.queue.splice(state.queue.indexOf(id), 1);
      delete state.pendingWants[id];
      state.orders[id] = status;
    } else {
      state.rejected = state.rejected + 1;
    }
    return undefined;
  };
}

const handleCancel = handleRelease("cancelled", true);

const handleShip: Handler = (state, event, index) => {
  const idErr = needId(event, index);
  if (idErr) return idErr;
  const qtyErr = needQty(event.qty, index, false);
  if (qtyErr) return qtyErr;
  const id = event.id as string;
  const reserved = state.reserved[id];
  if (reserved === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === reserved.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < reserved.qty) {
    reserved.qty = reserved.qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return undefined;
};

const handleRestock: Handler = (state, event, index) => {
  const itemErr = needItem(event, index);
  if (itemErr) return itemErr;
  const qtyErr = needQty(event.qty, index, true);
  if (qtyErr) return qtyErr;
  addStock(state, event.item as string, event.qty as number);
  return undefined;
};

const handleExpire = handleRelease("expired", false);

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

type ParsedInput =
  | { ok: true; stock: Record<string, number>; events: unknown[] }
  | { ok: false; error: string };

function parseStock(rawStock: unknown): { ok: true; stock: Record<string, number> } | { ok: false; error: string } {
  if (typeof rawStock !== "object" || rawStock === null) {
    return { ok: false, error: "bad stock" };
  }
  const source = rawStock as Record<string, unknown>;
  const stock: Record<string, number> = {};
  for (const item of Object.keys(source)) {
    const value = source[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = value as number;
  }
  return { ok: true, stock };
}

function parseInput(raw: unknown): ParsedInput {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stockResult = parseStock(input.stock);
  if (!stockResult.ok) {
    return { ok: false, error: stockResult.error };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, stock: stockResult.stock, events: input.events as unknown[] };
}

function runEvents(state: FulfillmentState, events: unknown[]): FulfillmentResult | undefined {
  for (let index = 0; index < events.length; index++) {
    const event = events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return badEvent(index, "malformed");
    }
    const handler = HANDLERS[event.type as string];
    if (!handler) {
      return badEvent(index, "bad type");
    }
    const error = handler(state, event, index);
    if (error) {
      return error;
    }
  }
  return undefined;
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  const state: FulfillmentState = {
    stock: parsed.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };
  const error = runEvents(state, parsed.events);
  if (error) {
    return error;
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

