import { processEvents as newFn } from "./process_events";
import { processEvents as oldFn } from "./orig";

function rnd(n: number): number { return Math.floor(Math.random() * n); }

function makeCase(): any {
  const types = ["order","cancel","ship","restock","expire"];
  const items = ["a","b","c"];
  const stock: Record<string, number> = {};
  if (Math.random() < 0.7) for (const it of items) if (Math.random()<0.7) stock[it] = rnd(10);
  const events: any[] = [];
  const n = rnd(15);
  let idc = 0;
  for (let i=0;i<n;i++){
    const t = types[rnd(types.length)];
    const e: any = { type: t };
    if (t==="order"){ e.id = "o"+(idc++); e.item = items[rnd(3)]; e.qty = 1+rnd(8); }
    else if (t==="cancel" || t==="expire"){ e.id = (Math.random()<0.5)?"o"+rnd(idc||1) : "x"+rnd(5); }
    else if (t==="ship"){ e.id = (Math.random()<0.5)?"o"+rnd(idc||1):"x"+rnd(5); if(Math.random()<0.5) e.qty = 1+rnd(8); }
    else { e.item = items[rnd(3)]; e.qty = 1+rnd(8); }
    if (Math.random()<0.08) e.id = 5;
    if (Math.random()<0.08) e.qty = 0;
    events.push(e);
  }
  // malformed cases
  if (Math.random()<0.08) return "malformed";
  if (Math.random()<0.08) return { stock: 5, events: [] };
  if (Math.random()<0.08) return { stock: {a:1}, events: {bad:true} };
  if (Math.random()<0.08) return { stock: {a: -1}, events: [] };
  return { stock, events };
}

let mismatches = 0;
for (let t=0;t<200000;t++){
  const c = makeCase();
  const a = JSON.stringify(oldFn(c));
  const b = JSON.stringify(newFn(c));
  if (a!==b){
    mismatches++;
    if (mismatches<=10) console.log("MISMATCH", JSON.stringify(c), "\n old:", a, "\n new:", b);
  }
}
console.log("done mismatches:", mismatches);

