export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  nightsMin: number;
  nightsMax: number;
  guestsMin: number;
  guestsMax: number;
  ratePerNight: number;
  highSurchargePerNight: number;
  minStay?: number;
  extraFee?: (guests: number) => number;
}

const CATEGORIES: CategoryConfig[] = [
  {
    name: "standard",
    nightsMin: 1,
    nightsMax: 14,
    guestsMin: 1,
    guestsMax: 2,
    ratePerNight: 80,
    highSurchargePerNight: 30,
  },
  {
    name: "suite",
    nightsMin: 1,
    nightsMax: 21,
    guestsMin: 1,
    guestsMax: 4,
    ratePerNight: 150,
    highSurchargePerNight: 60,
    extraFee: (guests) => (guests > 2 ? 25 : 0),
  },
  {
    name: "villa",
    nightsMin: 1,
    nightsMax: 28,
    guestsMin: 1,
    guestsMax: 8,
    ratePerNight: 300,
    highSurchargePerNight: 120,
    minStay: 3,
    extraFee: () => 500,
  },
];

interface ValidRequest {
  category: CategoryConfig;
  nights: number;
  guests: number;
  season: string;
  loyalty: number;
  coupon?: string;
}

type ParseResult = { ok: true; req: ValidRequest } | { ok: false; error: string };

function isObject(raw: unknown): raw is Record<string, unknown> {
  return typeof raw === "object" && raw !== null;
}

function isBadLoyalty(req: Record<string, unknown>): boolean {
  return !Number.isInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0;
}

function categoryOf(req: Record<string, unknown>): CategoryConfig | undefined {
  return CATEGORIES.find((c) => c.name === req.category);
}

function isBadNights(req: Record<string, unknown>, cfg: CategoryConfig): boolean {
  const n = req.nights as number;
  return !Number.isInteger(n) || n < cfg.nightsMin || n > cfg.nightsMax;
}

function isBelowMinStay(req: Record<string, unknown>, cfg: CategoryConfig): boolean {
  return cfg.minStay !== undefined && (req.nights as number) < cfg.minStay;
}

function isBadGuests(req: Record<string, unknown>, cfg: CategoryConfig): boolean {
  const g = req.guests as number;
  return !Number.isInteger(g) || g < cfg.guestsMin || g > cfg.guestsMax;
}

function isBadSeason(req: Record<string, unknown>): boolean {
  return req.season !== "low" && req.season !== "high";
}

function parseRequest(raw: unknown): ParseResult {
  if (!isObject(raw)) {
    return { ok: false, error: "malformed request" };
  }
  if (isBadLoyalty(raw)) {
    return { ok: false, error: "bad loyalty" };
  }
  const cfg = categoryOf(raw);
  if (!cfg) {
    return { ok: false, error: "unknown category" };
  }
  if (isBadNights(raw, cfg)) {
    return { ok: false, error: "bad nights" };
  }
  if (isBelowMinStay(raw, cfg)) {
    return { ok: false, error: cfg.name + " minimum stay" };
  }
  if (isBadGuests(raw, cfg)) {
    return { ok: false, error: "bad guests" };
  }
  if (isBadSeason(raw)) {
    return { ok: false, error: "bad season" };
  }
  const req: ValidRequest = {
    category: cfg,
    nights: raw.nights as number,
    guests: raw.guests as number,
    season: raw.season as string,
    loyalty: raw.loyaltyYears as number,
    coupon: raw.coupon as string | undefined,
  };
  return { ok: true, req };
}

function totalFor(req: ValidRequest): number {
  let total = req.category.ratePerNight * req.nights;
  if (req.season === "high") {
    total = total + req.category.highSurchargePerNight * req.nights;
  }
  return total;
}

function buildQuote(req: ValidRequest): QuoteResult {
  const preferred = req.loyalty >= 3 || req.coupon === "VIP";
  let total = totalFor(req);
  if (preferred) {
    total = total - Math.floor(total / 10);
  }
  if (req.category.extraFee) {
    total = total + req.category.extraFee(req.guests);
  }
  const policy = preferred ? "flex" : "strict";
  const line = req.category.name + ":" + String(req.nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  return buildQuote(parsed.req);
}

files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

interface FulfillCtx {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

const hasStock = (stock: Record<string, number>, item: string): number => stock[item] ?? 0;

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 1;
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function eventError(index: number, detail: string): FulfillmentResult {
  return { ok: false, error: "event " + index + ": " + detail };
}

function fulfillQueue(ctx: FulfillCtx): void {
  let position = 0;
  while (position < ctx.queue.length) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = hasStock(ctx.stock, want.item);
    if (onHand < want.qty) {
      position++;
      continue;
    }
    ctx.stock[want.item] = onHand - want.qty;
    ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
    ctx.orders[pendingId] = "reserved";
    delete ctx.pendingWants[pendingId];
    ctx.queue.splice(position, 1);
  }
}

function releaseReservation(ctx: FulfillCtx, id: string, finalStatus: string): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = hasStock(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = finalStatus;
  fulfillQueue(ctx);
}

function handleOrder(ctx: FulfillCtx, event: Record<string, unknown>, index: number): FulfillmentResult | null {
  if (!isNonEmptyString(event.id)) {
    return eventError(index, "bad id");
  }
  if (ctx.orders[event.id] !== undefined) {
    return eventError(index, "duplicate order");
  }
  if (!isNonEmptyString(event.item)) {
    return eventError(index, "bad item");
  }
  if (!isPositiveInt(event.qty)) {
    return eventError(index, "bad qty");
  }
  const available = hasStock(ctx.stock, event.item);
  if (available >= (event.qty as number)) {
    ctx.stock[event.item] = available - (event.qty as number);
    ctx.reserved[event.id] = { item: event.item, qty: event.qty as number };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
    ctx.orders[event.id] = "backordered";
  }
  return null;
}

function handleCancel(ctx: FulfillCtx, event: Record<string, unknown>, index: number): FulfillmentResult | null {
  if (!isNonEmptyString(event.id)) {
    return eventError(index, "bad id");
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id, "cancelled");
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected++;
  }
  return null;
}

function handleShip(ctx: FulfillCtx, event: Record<string, unknown>, index: number): FulfillmentResult | null {
  if (!isNonEmptyString(event.id)) {
    return eventError(index, "bad id");
  }
  if (event.qty !== undefined && !isPositiveInt(event.qty)) {
    return eventError(index, "bad qty");
  }
  const holding = ctx.reserved[event.id];
  if (holding === undefined) {
    ctx.rejected++;
  } else if (event.qty === undefined || (event.qty as number) === holding.qty) {
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "shipped";
  } else if ((event.qty as number) < holding.qty) {
    holding.qty = holding.qty - (event.qty as number);
    ctx.orders[event.id] = "partial";
  } else {
    ctx.rejected++;
  }
  return null;
}

function handleRestock(ctx: FulfillCtx, event: Record<string, unknown>, index: number): FulfillmentResult | null {
  if (!isNonEmptyString(event.item)) {
    return eventError(index, "bad item");
  }
  if (!isPositiveInt(event.qty)) {
    return eventError(index, "bad qty");
  }
  ctx.stock[event.item] = hasStock(ctx.stock, event.item) + (event.qty as number);
  fulfillQueue(ctx);
  return null;
}

function handleExpire(ctx: FulfillCtx, event: Record<string, unknown>, index: number): FulfillmentResult | null {
  if (!isNonEmptyString(event.id)) {
    return eventError(index, "bad id");
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id, "expired");
  } else {
    ctx.rejected++;
  }
  return null;
}

const HANDLERS: Record<string, (ctx: FulfillCtx, event: Record<string, unknown>, index: number) => FulfillmentResult | null> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function parseStock(rawStock: Record<string, unknown>): { stock: Record<string, number> } | FulfillmentResult {
  const stock: Record<string, number> = {};
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInt(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { stock };
}

function runEvents(ctx: FulfillCtx, events: Record<string, unknown>[]): FulfillmentResult | null {
  for (let index = 0; index < events.length; index++) {
    const event = events[index];
    if (typeof event !== "object" || event === null) {
      return eventError(index, "malformed");
    }
    const handler = HANDLERS[event.type as string];
    if (handler === undefined) {
      return eventError(index, "bad type");
    }
    const failure = handler(ctx, event, index);
    if (failure !== null) {
      return failure;
    }
  }
  return null;
}

function isFailure(result: { stock: Record<string, number> } | FulfillmentResult): result is FulfillmentResult {
  return "ok" in result;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const parsed = parseStock(input.stock as Record<string, unknown>);
  if (isFailure(parsed)) {
    return parsed;
  }

  const ctx: FulfillCtx = {
    stock: parsed.stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  const failure = runEvents(ctx, input.events as Record<string, unknown>[]);
  if (failure !== null) {
    return failure;
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

