    case "order":
      return applyOrder(event, index, state);
    case "cancel":
      return applyCancel(event, index, state);
    case "ship":
      return applyShip(event, index, state);
    case "restock":
      return applyRestock(event, index, state);
    case "expire":
      return applyExpire(event, index, state);
    default:
      return "event " + index + ": bad type";
  }
}

