const tree = parser.parse(src);
const CC_DECISION = new Set(["if_statement","for_statement","for_in_statement","while_statement","do_statement","catch_clause","switch_case"]);
const LOGICAL = new Set(["&&","||","??","&&=","||=","??="]);
const FN = new Set(["function_declaration","function_expression","arrow_function","method_definition","generator_function_declaration","generator_function"]);
function isDecision(n){
  if(CC_DECISION.has(n.type)) return true;
  if(n.type==="ternary_expression") return true;
  if((n.type==="binary_expression"||n.type==="augmented_assignment_expression")){
    const op=n.childForFieldName("operator");
    if(op && LOGICAL.has(op.text)) return true;
  }
  return false;
}
function ccOf(fn){
  let count=1;
  const visit=(node,isRoot)=>{
    if(!isRoot&&FN.has(node.type)) return;
    if(isDecision(node)) count+=1;
    for(const c of node.namedChildren) visit(c,false);
  };
  visit(fn,true);
  return count;
}
