  if(seen.has(cap.node.startIndex)) continue;
  seen.add(cap.node.startIndex);
  const nameNode=cap.node.childForFieldName("name");
  const name=nameNode?nameNode.text:cap.node.type;
  if(!FN.has(cap.node.type)) continue;
  const cc=ccOf(cap.node);
  dp+=cc;
  console.log(name,"cc="+cc);
}
console.log("decisionPoints="+(dp-seen.size));

