    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const e = event as Record<string, unknown>;

    switch (e.type) {
      case "order": {
        if (!isId(e.id)) {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (orders[e.id] !== undefined) {
          return { ok: false, error: "event " + index + ": duplicate order" };
        }
        if (!isId(e.item)) {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isQty(e.qty)) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        const available = onHand(stock, e.item);
        if (available >= e.qty) {
          stock[e.item] = available - e.qty;
          reserved[e.id] = { item: e.item, qty: e.qty };
          orders[e.id] = "reserved";
        } else {
          queue.push(e.id);
          pendingWants[e.id] = { item: e.item, qty: e.qty };
          orders[e.id] = "backordered";
        }
        break;
      }

      case "cancel": {
        if (!isId(e.id)) {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[e.id] !== undefined) {
          const holding = reserved[e.id];
          stock[holding.item] = onHand(stock, holding.item) + holding.qty;
          delete reserved[e.id];
          orders[e.id] = "cancelled";
          fillQueue(stock, queue, pendingWants, reserved, orders);
        } else if (orders[e.id] === "backordered") {
          queue.splice(queue.indexOf(e.id), 1);
          delete pendingWants[e.id];
          orders[e.id] = "cancelled";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "ship": {
        if (!isId(e.id)) {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (e.qty !== undefined && !isQty(e.qty)) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        if (reserved[e.id] === undefined) {
          rejected = rejected + 1;
        } else if (e.qty === undefined || e.qty === reserved[e.id].qty) {
          delete reserved[e.id];
          orders[e.id] = "shipped";
        } else if (e.qty < reserved[e.id].qty) {
          reserved[e.id].qty = reserved[e.id].qty - e.qty;
          orders[e.id] = "partial";
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      case "restock": {
        if (!isId(e.item)) {
          return { ok: false, error: "event " + index + ": bad item" };
        }
        if (!isQty(e.qty)) {
          return { ok: false, error: "event " + index + ": bad qty" };
        }
        stock[e.item] = onHand(stock, e.item) + e.qty;
        fillQueue(stock, queue, pendingWants, reserved, orders);
        break;
      }

      case "expire": {
        if (!isId(e.id)) {
          return { ok: false, error: "event " + index + ": bad id" };
        }
        if (reserved[e.id] !== undefined) {
          const holding = reserved[e.id];
          stock[holding.item] = onHand(stock, holding.item) + holding.qty;
          delete reserved[e.id];
          orders[e.id] = "expired";
          fillQueue(stock, queue, pendingWants, reserved, orders);
        } else {
          rejected = rejected + 1;
        }
        break;
      }

      default:
        return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

type Err = string | null;

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface EventContext {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  orders: Record<string, string>;
  queue: string[];
  rejected: number;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function requireId(event: Record<string, unknown>, index: number): Err {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return "event " + index + ": bad id";
  }
  return null;
}

function requireItem(event: Record<string, unknown>, index: number): Err {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return "event " + index + ": bad item";
  }
  return null;
}

function requirePositiveInt(value: unknown, index: number): Err {
  if (!Number.isInteger(value) || (value as number) < 1) {
    return "event " + index + ": bad qty";
  }
  return null;
}

function fulfillQueue(ctx: EventContext): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const available = onHand(ctx.stock, want.item);
    if (available >= want.qty) {
      ctx.stock[want.item] = available - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReservation(id: string, status: "cancelled" | "expired", ctx: EventContext): void {
  const holding = ctx.reserved[id];
  ctx.stock[holding.item] = onHand(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[id];
  ctx.orders[id] = status;
  fulfillQueue(ctx);
}

function handleOrder(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  const idError = requireId(event, index);
  if (idError !== null) return idError;
  if (ctx.orders[event.id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  const itemError = requireItem(event, index);
  if (itemError !== null) return itemError;
  const qtyError = requirePositiveInt(event.qty, index);
  if (qtyError !== null) return qtyError;
  const item = event.item as string;
  const qty = event.qty as number;
  const available = onHand(ctx.stock, item);
  if (available >= qty) {
    ctx.stock[item] = available - qty;
    ctx.reserved[event.id] = { item, qty };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item, qty };
    ctx.orders[event.id] = "backordered";
  }
  return null;
}

function handleCancel(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  const idError = requireId(event, index);
  if (idError !== null) return idError;
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, "cancelled", ctx);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleShip(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  const idError = requireId(event, index);
  if (idError !== null) return idError;
  if (event.qty !== undefined) {
    const qtyError = requirePositiveInt(event.qty, index);
    if (qtyError !== null) return qtyError;
  }
  const id = event.id as string;
  const held = ctx.reserved[id];
  if (held === undefined) {
    ctx.rejected = ctx.rejected + 1;
    return null;
  }
  const qty = event.qty === undefined ? held.qty : (event.qty as number);
  if (qty === held.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if (qty < held.qty) {
    held.qty = held.qty - qty;
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

function handleRestock(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  const itemError = requireItem(event, index);
  if (itemError !== null) return itemError;
  const qtyError = requirePositiveInt(event.qty, index);
  if (qtyError !== null) return qtyError;
  const item = event.item as string;
  ctx.stock[item] = onHand(ctx.stock, item) + (event.qty as number);
  fulfillQueue(ctx);
  return null;
}

function handleExpire(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  const idError = requireId(event, index);
  if (idError !== null) return idError;
  const id = event.id as string;
  if (ctx.reserved[id] !== undefined) {
    releaseReservation(id, "expired", ctx);
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, (event: Record<string, unknown>, index: number, ctx: EventContext) => Err> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function processEvent(event: Record<string, unknown>, index: number, ctx: EventContext): Err {
  if (typeof event !== "object" || event === null) {
    return "event " + index + ": malformed";
  }
  const handler = HANDLERS[event.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(event, index, ctx);
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

function parseStock(input: Record<string, unknown>): { ok: true; stock: Record<string, number> } | { ok: false; error: string } {
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  return { ok: true, stock };
}

function parseInput(raw: unknown): { ok: true; ctx: EventContext } | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  const stockResult = parseStock(input);
  if (!stockResult.ok) {
    return stockResult;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return {
    ok: true,
    ctx: {
      stock: stockResult.stock,
      reserved: {},
      pendingWants: {},
      orders: {},
      queue: [],
      rejected: 0,
    },
  };
}

function runEvents(events: unknown[], ctx: EventContext): Err {
  for (let index = 0; index < events.length; index++) {
    const error = processEvent(events[index] as Record<string, unknown>, index, ctx);
    if (error !== null) {
      return error;
    }
  }
  return null;
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if (!parsed.ok) {
    return { ok: false, error: parsed.error };
  }
  const error = runEvents((raw as Record<string, unknown>).events as unknown[], parsed.ctx);
  if (error !== null) {
    return { ok: false, error: error };
  }
  return {
    ok: true,
    orders: parsed.ctx.orders,
    stock: parsed.ctx.stock,
    queue: parsed.ctx.queue,
    rejected: parsed.ctx.rejected,
    report: buildReport(parsed.ctx.orders, parsed.ctx.rejected),
  };
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function onHand(stock: Record<string, number>, item: string): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

interface Context {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

interface Event {
  type?: unknown;
  id?: unknown;
  item?: unknown;
  qty?: unknown;
}

type Outcome = string | undefined;

function badEvent(index: number, reason: string): string {
  return "event " + index + ": " + reason;
}

function handleOrder(ctx: Context, event: Event, index: number): Outcome {
  if (!isNonEmptyString(event.id)) {
    return badEvent(index, "bad id");
  }
  if (ctx.orders[event.id] !== undefined) {
    return badEvent(index, "duplicate order");
  }
  if (!isNonEmptyString(event.item)) {
    return badEvent(index, "bad item");
  }
  if (!isPositiveInt(event.qty)) {
    return badEvent(index, "bad qty");
  }
  const want: Want = { item: event.item, qty: event.qty };
  if (onHand(ctx.stock, want.item) >= want.qty) {
    ctx.stock[want.item] = onHand(ctx.stock, want.item) - want.qty;
    ctx.reserved[event.id] = want;
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = want;
    ctx.orders[event.id] = "backordered";
  }
  return undefined;
}

function grantFromQueue(ctx: Context, orderId: string): void {
  const want = ctx.pendingWants[orderId];
  const available = onHand(ctx.stock, want.item);
  if (available < want.qty) {
    return;
  }
  ctx.stock[want.item] = available - want.qty;
  ctx.reserved[orderId] = { item: want.item, qty: want.qty };
  ctx.orders[orderId] = "reserved";
  delete ctx.pendingWants[orderId];
  ctx.queue.splice(ctx.queue.indexOf(orderId), 1);
}

function replenishQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    grantFromQueue(ctx, ctx.queue[position]);
  }
}

function releaseReservation(ctx: Context, orderId: string, status: string): void {
  const holding = ctx.reserved[orderId];
  ctx.stock[holding.item] = onHand(ctx.stock, holding.item) + holding.qty;
  delete ctx.reserved[orderId];
  ctx.orders[orderId] = status;
  replenishQueue(ctx);
}

function handleCancel(ctx: Context, event: Event, index: number): Outcome {
  if (!isNonEmptyString(event.id)) {
    return badEvent(index, "bad id");
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id, "cancelled");
  } else if (ctx.orders[event.id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(event.id), 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleShip(ctx: Context, event: Event, index: number): Outcome {
  if (!isNonEmptyString(event.id)) {
    return badEvent(index, "bad id");
  }
  if (event.qty !== undefined && !isPositiveInt(event.qty)) {
    return badEvent(index, "bad qty");
  }
  const holding = ctx.reserved[event.id];
  if (holding === undefined) {
    ctx.rejected = ctx.rejected + 1;
  } else if (event.qty === undefined || event.qty === holding.qty) {
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "shipped";
  } else if (event.qty < holding.qty) {
    holding.qty = holding.qty - event.qty;
    ctx.orders[event.id] = "partial";
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

function handleRestock(ctx: Context, event: Event, index: number): Outcome {
  if (!isNonEmptyString(event.item)) {
    return badEvent(index, "bad item");
  }
  if (!isPositiveInt(event.qty)) {
    return badEvent(index, "bad qty");
  }
  ctx.stock[event.item] = onHand(ctx.stock, event.item) + event.qty;
  replenishQueue(ctx);
  return undefined;
}

function handleExpire(ctx: Context, event: Event, index: number): Outcome {
  if (!isNonEmptyString(event.id)) {
    return badEvent(index, "bad id");
  }
  if (ctx.reserved[event.id] !== undefined) {
    releaseReservation(ctx, event.id, "expired");
  } else {
    ctx.rejected = ctx.rejected + 1;
  }
  return undefined;
}

const HANDLERS: Record<string, (ctx: Context, event: Event, index: number) => Outcome> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }

  const ctx: Context = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: badEvent(index, "malformed") };
    }
    const handler = HANDLERS[(event as Event).type as string];
    if (handler === undefined) {
      return { ok: false, error: badEvent(index, "bad type") };
    }
    const error = handler(ctx, event as Event, index);
    if (error !== undefined) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

