from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_TIERS = ("basic", "gold")
VALID_METHODS = ("card", "transfer")


def _validate_tier(member: dict) -> str | None:
    """Return an error string if the member's tier is invalid, else None."""
    if member["tier"] not in VALID_TIERS:
        return "unknown tier"
    return None


def _validate_payment(payment: dict) -> str | None:
    """Return an error string if the payment is invalid, else None."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in VALID_METHODS:
        return "unsupported method"
    return None


def _receipt(member_id: str, status: str, fee: int, method: str) -> str:
    """Build the receipt string for a successful renewal."""
    prefix = "card" if method == "card" else "transfer"
    return f"{prefix}:{member_id}:{status}:{fee}"


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or not member["id"]:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    if status == "active":
        err = _validate_tier(member)
        if err:
            return {"ok": False, "error": err}
        err = _validate_payment(payment)
        if err:
            return {"ok": False, "error": err}
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {"ok": True, "status": "renewed", "fee": fee,
                "receipt": _receipt(member["id"], "renewed", fee, payment["method"])}

    if status == "lapsed":
        err = _validate_tier(member)
        if err:
            return {"ok": False, "error": err}
        if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return {"ok": False, "error": "bad expiry"}
        err = _validate_payment(payment)
        if err:
            return {"ok": False, "error": err}
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        return {"ok": True, "status": new_status, "fee": fee,
                "receipt": _receipt(member["id"], new_status, fee, payment["method"])}

    if status == "suspended":
        err = _validate_tier(member)
        if err:
            return {"ok": False, "error": err}
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
