interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface State {
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

type Handler = (
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
) => string | null;

function isName(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveInt(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function requireId(value: unknown, index: number): string | null {
  return isName(value) ? value : null;
}

function processQueue(stock: Record<string, number>, state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const pendingId = state.queue[position];
    const want = state.pendingWants[pendingId];
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      state.reserved[pendingId] = { item: want.item, qty: want.qty };
      state.orders[pendingId] = "reserved";
      delete state.pendingWants[pendingId];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function releaseReserved(
  stock: Record<string, number>,
  state: State,
  id: string,
  status: string
): void {
  const holding = state.reserved[id];
  stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
  delete state.reserved[id];
  state.orders[id] = status;
  processQueue(stock, state);
}

function orderHandler(
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
): string | null {
  const id = requireId(event.id, index);
  if (id === null) {
    return "event " + index + ": bad id";
  }
  if (state.orders[id] !== undefined) {
    return "event " + index + ": duplicate order";
  }
  if (!isName(event.item)) {
    return "event " + index + ": bad item";
  }
  if (!isPositiveInt(event.qty)) {
    return "event " + index + ": bad qty";
  }
  const qty = event.qty as number;
  const available = stock[event.item] ?? 0;
  if (available >= qty) {
    stock[event.item] = available - qty;
    state.reserved[id] = { item: event.item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item: event.item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function cancelHandler(
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
): string | null {
  const id = requireId(event.id, index);
  if (id === null) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[id] !== undefined) {
    releaseReserved(stock, state, id, "cancelled");
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function shipHandler(
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
): string | null {
  const id = requireId(event.id, index);
  if (id === null) {
    return "event " + index + ": bad id";
  }
  if (event.qty !== undefined && !isPositiveInt(event.qty)) {
    return "event " + index + ": bad qty";
  }
  const holding = state.reserved[id];
  if (holding === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || event.qty === holding.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < holding.qty) {
    holding.qty = holding.qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function restockHandler(
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
): string | null {
  if (!isName(event.item)) {
    return "event " + index + ": bad item";
  }
  if (!isPositiveInt(event.qty)) {
    return "event " + index + ": bad qty";
  }
  stock[event.item] = (stock[event.item] ?? 0) + (event.qty as number);
  processQueue(stock, state);
  return null;
}

function expireHandler(
  stock: Record<string, number>,
  state: State,
  event: Record<string, unknown>,
  index: number
): string | null {
  const id = requireId(event.id, index);
  if (id === null) {
    return "event " + index + ": bad id";
  }
  if (state.reserved[id] !== undefined) {
    releaseReserved(stock, state, id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const handlers: Record<string, Handler> = {
  order: orderHandler,
  cancel: cancelHandler,
  ship: shipHandler,
  restock: restockHandler,
  expire: expireHandler,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const value = rawStock[item];
    if (!Number.isInteger(value) || (value as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = value as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handler = handlers[(event as Record<string, unknown>).type as string];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const error = handler(stock, state, event as Record<string, unknown>, index);
    if (error !== null) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

