from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_METHODS = {"card", "transfer"}


def _error(reason: str) -> dict:
    return {"ok": False, "error": reason}


def _valid_tier(member: dict) -> bool:
    return member["tier"] in TIER_FEES


def _valid_payment(payment: dict) -> str | None:
    """Return an error reason if the payment amount/method are invalid, else None."""
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in VALID_METHODS:
        return "unsupported method"
    return None


def _success(member: dict, method: str, status: str, fee: int) -> dict:
    receipt = f"{method}:{member['id']}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _process_active(member: dict, payment: dict) -> dict:
    if not _valid_tier(member):
        return _error("unknown tier")
    reason = _valid_payment(payment)
    if reason is not None:
        return _error(reason)

    fee = TIER_FEES[member["tier"]]
    if payment["amount"] < fee:
        return _error("insufficient payment")
    return _success(member, payment["method"], "renewed", fee)


def _process_lapsed(member: dict, payment: dict) -> dict:
    if not _valid_tier(member):
        return _error("unknown tier")
    if "expired_days" not in member or not isinstance(member["expired_days"], int) \
            or member["expired_days"] < 0:
        return _error("bad expiry")
    reason = _valid_payment(payment)
    if reason is not None:
        return _error(reason)

    if member["expired_days"] <= GRACE_DAYS:
        status, surcharge = "renewed", LATE_FEE
    else:
        status, surcharge = "reinstated", REINSTATE_SURCHARGE

    fee = TIER_FEES[member["tier"]] + surcharge
    if payment["amount"] < fee:
        return _error("insufficient payment")
    return _success(member, payment["method"], status, fee)


def _process_suspended(member: dict, payment: dict) -> dict:
    if not _valid_tier(member):
        return _error("unknown tier")
    if "strikes" not in member or not isinstance(member["strikes"], int) \
            or member["strikes"] < 0:
        return _error("bad strikes")
    if member["strikes"] >= MAX_STRIKES:
        return _error("too many strikes")
    reason = _valid_payment(payment)
    if reason is not None:
        return _error(reason)

    fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
    if payment["amount"] < fee:
        return _error("insufficient payment")
    return _success(member, payment["method"], "reactivated", fee)


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _error("malformed input")

    # Field presence is validated before value-level checks (id, then fields).
    if "id" not in raw_member or "status" not in raw_member or "tier" not in raw_member:
        return _error("missing member field")
    if "amount" not in raw_payment or "method" not in raw_payment:
        return _error("missing payment field")

    member = raw_member
    payment = raw_payment

    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return _error("bad member id")

    status = member["status"]
    if status == "banned":
        return _error("member banned")

    if status == "active":
        return _process_active(member, payment)
    if status == "lapsed":
        return _process_lapsed(member, payment)
    if status == "suspended":
        return _process_suspended(member, payment)

    return _error("unknown status")

