interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

class State {
  stock: Record<string, number>;
  orders: Record<string, string> = {};
  reserved: Record<string, Want> = {};
  pendingWants: Record<string, Want> = {};
  queue: string[] = [];
  rejected = 0;

  constructor(stock: Record<string, number>) {
    this.stock = stock;
  }

  stockOf(item: string): number {
    return this.stock[item] === undefined ? 0 : this.stock[item];
  }

  release(id: string, status: string): void {
    const holding = this.reserved[id];
    this.stock[holding.item] = this.stockOf(holding.item) + holding.qty;
    delete this.reserved[id];
    this.orders[id] = status;
    this.drainQueue();
  }

  drainQueue(): void {
    for (let position = 0; position < this.queue.length; position++) {
      const pendingId = this.queue[position];
      const want = this.pendingWants[pendingId];
      const onHand = this.stockOf(want.item);
      if (onHand >= want.qty) {
        this.stock[want.item] = onHand - want.qty;
        this.reserved[pendingId] = { item: want.item, qty: want.qty };
        this.orders[pendingId] = "reserved";
        delete this.pendingWants[pendingId];
        this.queue.splice(position, 1);
        position = position - 1;
      }
    }
  }
}

type Handler = (state: State, event: Record<string, unknown>, index: number) => string | null;
type Validation = { ok: true; stock: Record<string, number>; events: unknown[] } | { ok: false; error: string };

function readString(event: Record<string, unknown>, key: string): string | undefined {
  const value = event[key];
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function readQty(event: Record<string, unknown>, key: string): number | undefined {
  const value = event[key];
  return Number.isInteger(value) && (value as number) >= 1 ? (value as number) : undefined;
}

function validateInput(raw: unknown): Validation {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock = parseStock(input.stock as Record<string, unknown>);
  if (stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return { ok: true, stock, events: input.events };
}

function applyEvent(state: State, rawEvent: unknown, index: number): string | null {
  if (typeof rawEvent !== "object" || rawEvent === null) {
    return "event " + index + ": malformed";
  }
  const event = rawEvent as Record<string, unknown>;
  const handler = HANDLERS[event.type as string];
  if (handler === undefined) {
    return "event " + index + ": bad type";
  }
  return handler(state, event, index);
}

function handleOrder(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = readString(event, "id");
  if (id === undefined) return "event " + index + ": bad id";
  if (state.orders[id] !== undefined) return "event " + index + ": duplicate order";
  const item = readString(event, "item");
  if (item === undefined) return "event " + index + ": bad item";
  const qty = readQty(event, "qty");
  if (qty === undefined) return "event " + index + ": bad qty";
  if (state.stockOf(item) >= qty) {
    state.stock[item] = state.stockOf(item) - qty;
    state.reserved[id] = { item, qty };
    state.orders[id] = "reserved";
  } else {
    state.queue.push(id);
    state.pendingWants[id] = { item, qty };
    state.orders[id] = "backordered";
  }
  return null;
}

function handleCancel(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = readString(event, "id");
  if (id === undefined) return "event " + index + ": bad id";
  if (state.reserved[id] !== undefined) {
    state.release(id, "cancelled");
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

function handleShip(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = readString(event, "id");
  if (id === undefined) return "event " + index + ": bad id";
  const qty = readQty(event, "qty");
  if (event.qty !== undefined && qty === undefined) return "event " + index + ": bad qty";
  const reservation = state.reserved[id];
  if (reservation === undefined) {
    state.rejected = state.rejected + 1;
    return null;
  }
  applyShipment(state, id, reservation, qty);
  return null;
}

function applyShipment(state: State, id: string, reservation: Want, qty: number | undefined): void {
  if (qty === undefined || qty === reservation.qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if (qty < reservation.qty) {
    state.reserved[id].qty = reservation.qty - qty;
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function handleRestock(state: State, event: Record<string, unknown>, index: number): string | null {
  const item = readString(event, "item");
  if (item === undefined) return "event " + index + ": bad item";
  const qty = readQty(event, "qty");
  if (qty === undefined) return "event " + index + ": bad qty";
  state.stock[item] = state.stockOf(item) + qty;
  state.drainQueue();
  return null;
}

function handleExpire(state: State, event: Record<string, unknown>, index: number): string | null {
  const id = readString(event, "id");
  if (id === undefined) return "event " + index + ": bad id";
  if (state.reserved[id] !== undefined) {
    state.release(id, "expired");
  } else {
    state.rejected = state.rejected + 1;
  }
  return null;
}

const HANDLERS: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  const input = validateInput(raw);
  if (!input.ok) {
    return { ok: false, error: input.error };
  }
  const state = new State(input.stock);
  for (let index = 0; index < input.events.length; index++) {
    const error = applyEvent(state, input.events[index], index);
    if (error !== null) {
      return { ok: false, error };
    }
  }
  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

function parseStock(raw: Record<string, unknown>): Record<string, number> | null {
  const stock: Record<string, number> = {};
  for (const item of Object.keys(raw)) {
    if (!Number.isInteger(raw[item]) || (raw[item] as number) < 0) {
      return null;
    }
    stock[item] = raw[item] as number;
  }
  return stock;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

class FulfillmentEngine {
  stock: Record<string, number>;
  orders: Record<string, string> = {};
  reserved: Record<string, Want> = {};
  pendingWants: Record<string, Want> = {};
  queue: string[] = [];
  rejected = 0;

  constructor(stock: Record<string, number>) {
    this.stock = stock;
  }

  private onHand(item: string): number {
    return this.stock[item] === undefined ? 0 : this.stock[item];
  }

  private release(item: string, qty: number): void {
    this.stock[item] = this.onHand(item) + qty;
  }

  private drainQueue(): void {
    for (let position = 0; position < this.queue.length; position++) {
      const pendingId = this.queue[position];
      const want = this.pendingWants[pendingId];
      if (this.onHand(want.item) >= want.qty) {
        this.stock[want.item] = this.onHand(want.item) - want.qty;
        this.reserved[pendingId] = { item: want.item, qty: want.qty };
        this.orders[pendingId] = "reserved";
        delete this.pendingWants[pendingId];
        this.queue.splice(position, 1);
        position = position - 1;
      }
    }
  }

  private validateOrder(id: unknown, item: unknown, qty: unknown, index: number): string | null {
    if (typeof id !== "string" || id.length === 0) return "event " + index + ": bad id";
    if (this.orders[id] !== undefined) return "event " + index + ": duplicate order";
    if (typeof item !== "string" || item.length === 0) return "event " + index + ": bad item";
    if (!Number.isInteger(qty) || (qty as number) < 1) return "event " + index + ": bad qty";
    return null;
  }

  private validateShip(id: unknown, qty: unknown, index: number): string | null {
    if (typeof id !== "string" || id.length === 0) return "event " + index + ": bad id";
    if (qty !== undefined && (!Number.isInteger(qty) || (qty as number) < 1)) {
      return "event " + index + ": bad qty";
    }
    return null;
  }

  order(id: unknown, item: unknown, qty: unknown, index: number): string | null {
    const err = this.validateOrder(id, item, qty, index);
    if (err !== null) return err;

    if (this.onHand(item as string) >= (qty as number)) {
      this.stock[item as string] = this.onHand(item as string) - (qty as number);
      this.reserved[id as string] = { item: item as string, qty: qty as number };
      this.orders[id as string] = "reserved";
    } else {
      this.queue.push(id as string);
      this.pendingWants[id as string] = { item: item as string, qty: qty as number };
      this.orders[id as string] = "backordered";
    }
    return null;
  }

  cancel(id: unknown, index: number): string | null {
    if (typeof id !== "string" || id.length === 0) return "event " + index + ": bad id";

    if (this.reserved[id] !== undefined) {
      const holding = this.reserved[id];
      this.release(holding.item, holding.qty);
      delete this.reserved[id];
      this.orders[id] = "cancelled";
      this.drainQueue();
    } else if (this.orders[id] === "backordered") {
      this.queue.splice(this.queue.indexOf(id), 1);
      delete this.pendingWants[id];
      this.orders[id] = "cancelled";
    } else {
      this.rejected = this.rejected + 1;
    }
    return null;
  }

  ship(id: unknown, qty: unknown, index: number): string | null {
    const err = this.validateShip(id, qty, index);
    if (err !== null) return err;

    const hold = this.reserved[id as string];
    if (hold === undefined) {
      this.rejected = this.rejected + 1;
    } else if (qty === undefined || (qty as number) === hold.qty) {
      delete this.reserved[id as string];
      this.orders[id as string] = "shipped";
    } else if ((qty as number) < hold.qty) {
      hold.qty = hold.qty - (qty as number);
      this.orders[id as string] = "partial";
    } else {
      this.rejected = this.rejected + 1;
    }
    return null;
  }

  restock(item: unknown, qty: unknown, index: number): string | null {
    if (typeof item !== "string" || item.length === 0) return "event " + index + ": bad item";
    if (!Number.isInteger(qty) || (qty as number) < 1) return "event " + index + ": bad qty";

    this.release(item, qty as number);
    this.drainQueue();
    return null;
  }

  expire(id: unknown, index: number): string | null {
    if (typeof id !== "string" || id.length === 0) return "event " + index + ": bad id";

    if (this.reserved[id] !== undefined) {
      const holding = this.reserved[id];
      this.release(holding.item, holding.qty);
      delete this.reserved[id];
      this.orders[id] = "expired";
      this.drainQueue();
    } else {
      this.rejected = this.rejected + 1;
    }
    return null;
  }
}

type Handler = (
  engine: FulfillmentEngine,
  event: Record<string, unknown>,
  index: number
) => string | null;

const HANDLERS: Record<string, Handler> = {
  order: (engine, event, index) => engine.order(event.id, event.item, event.qty, index),
  cancel: (engine, event, index) => engine.cancel(event.id, index),
  ship: (engine, event, index) => engine.ship(event.id, event.qty, index),
  restock: (engine, event, index) => engine.restock(event.item, event.qty, index),
  expire: (engine, event, index) => engine.expire(event.id, index),
};

interface ParsedInput {
  stock: Record<string, number>;
  events: Record<string, unknown>[];
}

function parseStock(input: Record<string, unknown>): { stock: Record<string, number> } | { error: string } {
  const rawStock = input.stock;
  if (typeof rawStock !== "object" || rawStock === null) return { error: "bad stock" };
  const stock: Record<string, number> = {};
  const src = rawStock as Record<string, unknown>;
  for (const item of Object.keys(src)) {
    if (!Number.isInteger(src[item]) || (src[item] as number) < 0) return { error: "bad stock" };
    stock[item] = src[item] as number;
  }
  return { stock };
}

function parseEvents(input: Record<string, unknown>): { events: Record<string, unknown>[] } | { error: string } {
  if (!Array.isArray(input.events)) return { error: "bad events" };
  return { events: input.events as Record<string, unknown>[] };
}

function parseInput(raw: unknown): ParsedInput | { error: string } {
  if (typeof raw !== "object" || raw === null) return { error: "malformed input" };
  const input = raw as Record<string, unknown>;
  const stockParsed = parseStock(input);
  if ("error" in stockParsed) return { error: stockParsed.error };
  const eventsParsed = parseEvents(input);
  if ("error" in eventsParsed) return { error: eventsParsed.error };
  return { stock: stockParsed.stock, events: eventsParsed.events };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if ("error" in parsed) return { ok: false, error: parsed.error };

  const engine = new FulfillmentEngine(parsed.stock);

  for (let index = 0; index < parsed.events.length; index++) {
    const event = parsed.events[index];
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const type = event.type;
    const handler = typeof type === "string" ? HANDLERS[type] : undefined;
    if (handler === undefined) return { ok: false, error: "event " + index + ": bad type" };

    const error = handler(engine, event, index);
    if (error !== null) return { ok: false, error };
  }

  return {
    ok: true,
    orders: engine.orders,
    stock: engine.stock,
    queue: engine.queue,
    rejected: engine.rejected,
    report: buildReport(engine.orders, engine.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

