def _suspended_check(member: dict) -> dict | None:
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    return None


def _active_resolve(member: dict) -> tuple[str, int]:
    return "renewed", TIER_FEES[member["tier"]]


def _lapsed_resolve(member: dict) -> tuple[str, int]:
    if member["expired_days"] <= GRACE_DAYS:
        return "renewed", TIER_FEES[member["tier"]] + LATE_FEE
    return "reinstated", TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE


def _suspended_resolve(member: dict) -> tuple[str, int]:
    base = TIER_FEES[member["tier"]]
    return "reactivated", base + base // 2


_HANDLERS = {
    "active": (_active_check, _active_resolve),
    "lapsed": (_lapsed_check, _lapsed_resolve),
    "suspended": (_suspended_check, _suspended_resolve),
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
