    if status == "banned":
        return {"ok": False, "error": "member banned"}

    handler = _HANDLERS.get(status)
    if handler is None:
        return {"ok": False, "error": "unknown status"}

    check, resolve = handler
    if member["tier"] not in TIER_FEES:
        return _ERR_UNKNOWN_TIER
    specific_error = check(member)
    if specific_error is not None:
        return specific_error
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return _ERR_BAD_AMOUNT
    if payment["method"] not in _SUPPORTED_METHODS:
        return _ERR_UNSUPPORTED_METHOD

    result_status, fee = resolve(member)
    if payment["amount"] < fee:
        return _ERR_INSUFFICIENT

    return {"ok": True, "status": result_status, "fee": fee, "receipt": _receipt(member, payment, result_status, fee)}

