    """Return (fee, action) for the given member/status."""
    if status == "active":
        return base_fee, "renewed"
    if status == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            return base_fee + LATE_FEE, "renewed"
        return base_fee + REINSTATE_SURCHARGE, "reinstated"
