from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_VALID_TIERS = frozenset(TIER_FEES)
_VALID_METHODS = frozenset({"card", "transfer"})


def _validate(
    member: dict,
    payment: dict,
    extra: str | None = None,
    condition: object = None,
) -> str | None:
    """Return an error message for the per-status validation, or None if valid.

    Mirrors the original check ordering: tier, then the optional extra field,
    then an optional status-specific condition, then amount, then method.
    condition is a callable(member) -> error string or None.
    """
    if member["tier"] not in _VALID_TIERS:
        return "unknown tier"
    if extra == "expiry" and (
        "expired_days" not in member
        or not isinstance(member["expired_days"], int)
        or member["expired_days"] < 0
    ):
        return "bad expiry"
    if extra == "strikes" and (
        "strikes" not in member
        or not isinstance(member["strikes"], int)
        or member["strikes"] < 0
    ):
        return "bad strikes"
    if condition is not None:
        error = condition(member)
        if error is not None:
            return error
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return "bad amount"
    if payment["method"] not in _VALID_METHODS:
        return "unsupported method"
    return None


def _receipt(method: str, member_id: str, outcome: str, fee: int) -> str:
    return method + ":" + member_id + ":" + outcome + ":" + str(fee)


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment

    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]

    if status == "banned":
        return {"ok": False, "error": "member banned"}

    if status == "active":
        error = _validate(member, payment)
        if error is not None:
            return {"ok": False, "error": error}
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        receipt = _receipt(payment["method"], member["id"], "renewed", fee)
        return {"ok": True, "status": "renewed", "fee": fee, "receipt": receipt}

    if status == "lapsed":
        error = _validate(member, payment, "expiry")
        if error is not None:
            return {"ok": False, "error": error}
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        receipt = _receipt(payment["method"], member["id"], new_status, fee)
        return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

    if status == "suspended":
        error = _validate(
            member,
            payment,
            "strikes",
            lambda m: "too many strikes" if m["strikes"] >= MAX_STRIKES else None,
        )
        if error is not None:
            return {"ok": False, "error": error}
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        receipt = _receipt(payment["method"], member["id"], "reactivated", fee)
        return {"ok": True, "status": "reactivated", "fee": fee, "receipt": receipt}

    return {"ok": False, "error": "unknown status"}

